--
-- Déclencheurs `order_items`
--
DELIMITER $$
CREATE TRIGGER `trg_update_order_total_after_delete` AFTER DELETE ON `order_items` FOR EACH ROW BEGIN
  UPDATE orders
  SET total_price = (
    SELECT COALESCE(SUM(product.sale_price), 0)
    FROM order_items
    JOIN product ON order_items.product_id = product.id
    WHERE order_items.order_id = OLD.order_id
  )
  WHERE id = OLD.order_id$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_order_total_after_insert` AFTER INSERT ON `order_items` FOR EACH ROW BEGIN
  UPDATE orders
  SET total_price = (
    SELECT SUM(product.sale_price)
    FROM order_items
    JOIN product ON order_items.product_id = product.id
    WHERE order_items.order_id = NEW.order_id
  )
  WHERE id = NEW.order_id$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_order_total_after_update` AFTER UPDATE ON `order_items` FOR EACH ROW BEGIN
  UPDATE orders
  SET total_price = (
    SELECT SUM(product.sale_price)
    FROM order_items
    JOIN product ON order_items.product_id = product.id
    WHERE order_items.order_id = NEW.order_id
  )
  WHERE id = NEW.order_id$$
DELIMITER ;

